with feeders as (select * from (
    select
        md5(upper(HUB_POLICY_BK__K0)) as HUB_POLICY_HK,
        DO_YOU_WANT_TO_ASSIGN_THE_POLICY as ASSIGNMENT_INDICATOR,
        ASSIGNEE_NAME as ASSIGNEE_REFERENCE,
