        case when ASSIGNMENT_INDICATOR is not null or ASSIGNEE_REFERENCE is not null
             then md5(upper(coalesce(ASSIGNMENT_INDICATOR::varchar,'') || '||' || coalesce(ASSIGNEE_REFERENCE::varchar,'')))
        end as SAT_POLICY_LIFECYCLE_HASHDIFF
    from feeders)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_LIFECYCLE_HASHDIFF is not null
